from Crypto.Util.number import *

p = getPrime(512)
q = getPrime(512)
n = p * q
e = 7
d = inverse(e, (p - 1) * (q - 1))
flag = b"flag{this_is_known_flag_high_part}"
m = bytes_to_long(flag)
c = pow(m, e, n)

print(f"n = {n}")
print(f"e = {e}")
print(f"c = {c}")
print(f"m_high = {m >> 200}")

